const CACHE='chemlab-lab-1';const ASSETS=["./","app.js","element-learning.js","elements-data.js","engine.js","expansion.js","icon.svg","icons/app-192.png","icons/app-512.png","index.html","lab.webp","liquid.js","manifest.webmanifest","mission.js","preferences.js","privacy.html","progression.js","style.css","tube-glass.webp"];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('chemlab-lab-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(e.request.method==='GET'&&new URL(e.request.url).origin===location.origin)e.respondWith(fetch(e.request).catch(()=>caches.match(e.request,{ignoreSearch:true}).then(r=>r||Response.error())))});